class Employee:
    def __init__(self, name):
        self.name = name

    def describe(self):
        return self.name + " works here"

class Manager(Employee):
    def __init__(self, name, team):
        super().__init__(name)
        self.team = team

    def describe(self):
        return self.name + " leads " + str(self.team) + " people"

print(Employee("Amit").describe())
print(Manager("Meera", 6).describe())

class Circle:
    def __init__(self, r):
        self.r = r
    def area(self):
        return round(3.14159 * self.r ** 2, 2)

class Square:
    def __init__(self, side):
        self.side = side
    def area(self):
        return self.side ** 2

for shape in [Circle(3), Square(4)]:
    print(type(shape).__name__, "area:", shape.area())
